    while ((idx = text.indexOf('C105', idx)) !== -1) {
      console.log('Snippet C105:', text.slice(Math.max(0, idx - 50), idx + 100));
      idx += 4;
    }
    idx = 0;
    while ((idx = text.indexOf('씨105', idx)) !== -1) {
      console.log('Snippet 씨105:', text.slice(Math.max(0, idx - 50), idx + 100));
      idx += 4;
    }
